package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/JayveerPrajapati/kern/internal/app"
	kernctx "github.com/JayveerPrajapati/kern/internal/context"
	"github.com/JayveerPrajapati/kern/internal/eval"
)

// runEval implements `kern eval`: deterministic context-quality evaluation.
//
//   - kern eval run DIR      Evaluate baseline/candidate samples (one JSON file
//     per case: name, baseline, candidate, critical_evidence). A case that has
//     "intent" instead of "candidate" is generated by the silent pipeline
//     (kern orchestrate): baseline = the raw assembled packet render,
//     candidate = the planner-selected envelope render, latency measured.
//   - kern eval compare DIR A B   Run intent-based cases through two context
//     modes and report both results plus the winner (default modes: fix, review).
//   - kern eval report       Print the last stored run/compare result.
func runEval(rest []string) {
	f, args := parseFlagsOrDie(rest)
	if len(args) == 0 {
		fatalUsage("usage: kern eval <run|compare|report> [root] [--root ROOT] [--max-tokens N] [--mode MODE]")
	}
	switch args[0] {
	case "run":
		runEvalRun(f, args[1:])
	case "compare":
		runEvalCompare(f, args[1:])
	case "report":
		runEvalReport(f, args[1:])
	default:
		fatalUsage("unknown eval subcommand %q (want run|compare|report)", args[0])
	}
}

// evalDir resolves the cases directory from --eval DIR or the positional arg.
func evalDir(f flags, args []string) string {
	if f.evalDir != "" {
		return f.evalDir
	}
	if len(args) > 0 {
		return args[0]
	}
	return "."
}

// evalStorePath is the persistence location for the last eval result.
func evalStorePath(root string, name string) string {
	return filepath.Join(root, ".kern", "eval", name)
}

// evalPipeline generates candidates for intent-based cases through the silent
// pipeline and measures latency. Static cases pass through unchanged.
func evalPipeline(p *app.Platform, samples []eval.Sample, opts kernctx.OrchestrateOptions) ([]eval.Sample, int64) {
	out := make([]eval.Sample, 0, len(samples))
	var latencyMs int64
	for _, s := range samples {
		if s.Intent == "" {
			out = append(out, s)
			continue
		}
		// Baseline: the raw assembled packet render (the "no orchestration"
		// context an agent would otherwise read), unless the case provides one.
		baseline := s.Baseline
		if baseline == "" {
			if _, text, err := p.Analyze(s.Intent); err == nil {
				baseline = text
			}
		}
		start := time.Now()
		res, err := p.Orchestrate(s.Intent, opts)
		if err != nil {
			continue // a case that cannot assemble is skipped, not failed
		}
		latencyMs += time.Since(start).Milliseconds()
		// Candidate = the delivered render (FittedText carries the skill
		// section when opts.Skill is set; RenderPlan is the envelope-only
		// fallback).
		candidate := res.FittedText
		if candidate == "" {
			candidate = kernctx.RenderPlan(res.Plan)
		}
		out = append(out, eval.Sample{
			Name:             s.Name,
			Baseline:         baseline,
			Candidate:        candidate,
			CriticalEvidence: s.CriticalEvidence,
		})
	}
	return out, latencyMs
}

// evalRunStandard runs the harness over static samples and prints the result.
func evalRunStandard(f flags, dir string) {
	samples, err := eval.LoadSamplesFromDir(dir)
	if err != nil {
		fatal("Eval: %v", err)
	}
	if len(samples) == 0 {
		fatal("Eval: no sample files in %s (one JSON per case: name, baseline, candidate, critical_evidence)", dir)
	}
	h := eval.NewEvalHarness(samples, f.maxTokens, []eval.Assertion{
		eval.AssertEvidenceRetention(0.5),
		eval.AssertOmissionRate(0.5),
		eval.AssertErrorRate(0.5),
	})
	res := h.Run()
	saveEvalResult(f, res, "last.json")
	printEval(f, res)
}

// runEvalRun dispatches to the static or pipeline runner.
func runEvalRun(f flags, args []string) {
	dir := evalDir(f, args)
	samples, err := eval.LoadSamplesFromDir(dir)
	if err != nil {
		fatal("Eval: %v", err)
	}
	if len(samples) == 0 {
		fatal("Eval: no sample files in %s (one JSON per case: name, baseline, candidate, critical_evidence)", dir)
	}
	pipeline := false
	for _, s := range samples {
		if s.Intent != "" {
			pipeline = true
			break
		}
	}
	if !pipeline {
		evalRunStandard(f, dir)
		return
	}
	root := projectRoot(f)
	p, err := app.New(root)
	if err != nil {
		fatal("Eval: %v", err)
	}
	gen, latency := evalPipeline(p, samples, kernctx.OrchestrateOptions{Budget: f.maxTokens, Mode: f.mode, Skill: f.withSkill})
	h := eval.NewEvalHarness(gen, 0, []eval.Assertion{
		eval.AssertEvidenceRetention(0.5),
		eval.AssertOmissionRate(0.5),
		eval.AssertErrorRate(0.5),
	})
	res := h.Run()
	res.LatencyMs = latency
	saveEvalResult(f, res, "last.json")
	printEval(f, res)
}

// runEvalCompare runs intent-based cases through two modes and reports both.
func runEvalCompare(f flags, args []string) {
	dir := f.evalDir
	modeA, modeB := "fix", "review"
	if dir == "" {
		if len(args) > 0 {
			dir = args[0]
			args = args[1:]
		}
	}
	if dir == "" {
		fatalUsage("usage: kern eval compare [root] MODE_A MODE_B [--root ROOT] [--max-tokens N]")
	}
	if len(args) >= 1 {
		modeA = args[0]
	}
	if len(args) >= 2 {
		modeB = args[1]
	}
	root := projectRoot(f)
	p, err := app.New(root)
	if err != nil {
		fatal("Eval: %v", err)
	}
	samples, err := eval.LoadSamplesFromDir(dir)
	if err != nil {
		fatal("Eval: %v", err)
	}
	genA, latA := evalPipeline(p, samples, kernctx.OrchestrateOptions{Budget: f.maxTokens, Mode: modeA, Skill: f.withSkill})
	genB, latB := evalPipeline(p, samples, kernctx.OrchestrateOptions{Budget: f.maxTokens, Mode: modeB, Skill: f.withSkill})
	ra := eval.NewEvalHarness(genA, 0, nil).Run()
	ra.LatencyMs = latA
	rb := eval.NewEvalHarness(genB, 0, nil).Run()
	rb.LatencyMs = latB

	type comparison struct {
		ModeA  string          `json:"mode_a"`
		ModeB  string          `json:"mode_b"`
		A      eval.EvalResult `json:"a"`
		B      eval.EvalResult `json:"b"`
		Winner string          `json:"winner"` // "a" | "b" | "tie"
	}
	cmp := comparison{ModeA: modeA, ModeB: modeB, A: ra, B: rb}
	switch {
	case ra.Score > rb.Score:
		cmp.Winner = "a"
	case rb.Score > ra.Score:
		cmp.Winner = "b"
	default:
		cmp.Winner = "tie"
	}
	saveEvalResult(f, cmp, "compare.json")
	if f.json {
		printJSON(cmp)
		return
	}
	fmt.Printf("== compare: %s vs %s (%d cases) ==\n", modeA, modeB, len(genA))
	fmt.Printf("%-14s %8s %10s %10s %10s %10s\n", "mode", "score", "tok-reduc", "retention", "omission", "latency")
	for _, r := range []struct {
		name string
		res  eval.EvalResult
	}{{modeA, ra}, {modeB, rb}} {
		fmt.Printf("%-14s %8.1f %10.2f %10.2f %10.2f %10dms\n", r.name, r.res.Score, r.res.TokenReduction, r.res.EvidenceRetention, r.res.OmissionRate, r.res.LatencyMs)
	}
	fmt.Printf("winner: %s\n", cmp.Winner)
}

// runEvalReport prints the last stored result.
func runEvalReport(f flags, args []string) {
	root := projectRoot(f)
	path := evalStorePath(root, "last.json")
	data, err := os.ReadFile(path)
	if err != nil {
		fatal("Eval: no stored result at %s (run `kern eval run` first): %v", path, err)
	}
	var res eval.EvalResult
	if err := json.Unmarshal(data, &res); err != nil {
		fatal("Eval: corrupt stored result: %v", err)
	}
	printEval(f, res)
}

// saveEvalResult persists a result under <root>/.kern/eval/.
func saveEvalResult(f flags, v any, name string) {
	root := projectRoot(f)
	dir := filepath.Join(root, ".kern", "eval")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return // best-effort persistence never fails the command
	}
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return
	}
	_ = os.WriteFile(filepath.Join(dir, name), data, 0o644)
}

// printEval renders an EvalResult as JSON or a compact summary.
func printEval(f flags, res eval.EvalResult) {
	if f.json {
		printJSON(res)
		return
	}
	fmt.Printf("score: %.2f\n", res.Score)
	fmt.Printf("token_reduction: %.2f\n", res.TokenReduction)
	fmt.Printf("evidence_retention: %.2f\n", res.EvidenceRetention)
	fmt.Printf("omission_rate: %.2f\n", res.OmissionRate)
	fmt.Printf("error_rate: %.2f\n", res.ErrorRate)
	fmt.Printf("latency_ms: %d\n", res.LatencyMs)
	fmt.Printf("reproducible: %t\n", res.Reproducible)
	fmt.Printf("samples: %d\n", len(res.Samples))
}
